// @domain: domains
//! The door's rules (#4478, Silas's review point 1): generated into every binary,
//! above the store, so no backend can skip them. A write is checked against the
//! shape, the owner or a Write Permission, keeps the version it changes, and leaves
//! an event. Every refusal is typed.
//! Generated by athena-gen from its template — DO NOT EDIT; change the generator.

use crate::auth::Caller;
use crate::model::{ClassDef, FieldDef, NS};
use crate::store::{iri, Row, RowStore};
use serde_json::{json, Map, Value};

pub struct Refusal {
    pub code: u16,
    pub kind: &'static str,
    pub message: String,
}

fn refuse(code: u16, kind: &'static str, message: impl Into<String>) -> Refusal {
    Refusal { code, kind, message: message.into() }
}

/// A value the store will write: a link (full IRI) or a literal with its datatype.
pub enum Cell {
    Link(String),
    Literal(String, &'static str),
}

pub fn field<'a>(class: &'a ClassDef, name: &str) -> Option<&'a FieldDef> {
    class.fields.iter().find(|f| f.name == name)
}

/// A link value as an IRI. Accepts a full IRI, `chorus:x`, or a bare name; the target
/// must exist in the store, or the write is refused, never silently dropped (v1 requirement 4).
fn link_iri(store: &dyn RowStore, f: &FieldDef, v: &str) -> Result<String, Refusal> {
    let iri = if v.starts_with("http://") || v.starts_with("https://") {
        v.to_string()
    } else {
        format!("{NS}{}", v.strip_prefix("chorus:").unwrap_or(v))
    };
    match store.exists(&iri) {
        Ok(true) => Ok(iri),
        Ok(false) => Err(refuse(422, "unknown-target", format!("{}: no row {iri} to link to", f.name))),
        Err(m) => Err(refuse(503, "store", m)),
    }
}

/// Turn a JSON body into cells, field by field, against the shape. `allow_null` is
/// PATCH's "remove this field". Unknown fields, values outside sh:in, a list on a
/// one-value field, and dangling links are refused before anything is written.
pub fn cells(store: &dyn RowStore, class: &ClassDef, body: &Map<String, Value>, allow_null: bool)
    -> Result<Vec<(String, Vec<Cell>)>, Refusal> {
    let mut out = Vec::new();
    for (k, v) in body {
        if matches!(k.as_str(), "name" | "iri" | "ownedBy") {
            continue; // the key and the owner are the door's, not the caller's
        }
        if k == "label" || k == "status" {
            let s = v.as_str().ok_or_else(|| refuse(422, "bad-value", format!("{k} must be text")))?;
            out.push((k.clone(), vec![Cell::Literal(s.to_string(), "string")]));
            continue;
        }
        let f = field(class, k).ok_or_else(|| refuse(422, "off-model", format!("'{k}' is not a field of {}", class.name)))?;
        let values: Vec<String> = match v {
            Value::Null if allow_null => Vec::new(),
            Value::Null => return Err(refuse(422, "bad-value", format!("{k}: null only removes a field (PATCH)"))),
            Value::Array(a) if f.many => a.iter().map(|x| x.as_str().map(String::from).unwrap_or_else(|| x.to_string())).collect(),
            Value::Array(_) => return Err(refuse(422, "one-value", format!("{k} holds one value"))),
            Value::String(s) => vec![s.clone()],
            other => vec![other.to_string()],
        };
        let mut cs = Vec::new();
        for val in values {
            if !f.allowed.is_empty() && !f.allowed.contains(&val.as_str()) {
                return Err(refuse(422, "not-allowed", format!("{k}: '{val}' is not one of {:?}", f.allowed)));
            }
            cs.push(if f.link { Cell::Link(link_iri(store, f, &val)?) } else { Cell::Literal(val, f.datatype) });
        }
        out.push((k.clone(), cs));
    }
    Ok(out)
}

/// Who may write this row: its owner, or a caller holding a Write Permission on the
/// class's graph (v1 requirement 5).
pub fn may_write(class: &ClassDef, row: Option<&Row>, caller: &Caller) -> Result<(), Refusal> {
    let me = format!("principal-{}", caller.principal);
    let owner = row.and_then(|r| r.get("ownedBy")).and_then(Value::as_str).unwrap_or("");
    if owner == me || caller.scopes.iter().any(|g| g == class.graph) {
        return Ok(());
    }
    if owner.is_empty() {
        return Err(refuse(403, "no-permission", format!("{} has no owner and {} holds no Write Permission on {}", class.name, caller.principal, class.graph)));
    }
    Err(refuse(403, "not-owner", format!("owned by {owner}; {} holds no Write Permission on {}", caller.principal, class.graph)))
}

pub fn required_missing(class: &ClassDef, cells: &[(String, Vec<Cell>)]) -> Option<&'static str> {
    class.fields.iter()
        .filter(|f| f.required && f.name != "ownedBy")
        .find(|f| !cells.iter().any(|(k, v)| k == f.name && !v.is_empty()))
        .map(|f| f.name)
}

/// The version a write displaces, as the Version row v1 keeps (#4102): ofRow, writeCount, snapshot.
pub fn version_row(class: &ClassDef, name: &str, prior: &Row, count: usize) -> (String, Vec<(String, Vec<Cell>)>) {
    let s = format!("{NS}version-{}-{name}-{count}", class.plural);
    let snapshot = json!(prior).to_string();
    (s, vec![
        ("ofRow".into(), vec![Cell::Literal(format!("{}/{name}", class.plural), "string")]),
        ("writeCount".into(), vec![Cell::Literal(count.to_string(), "string")]),
        ("snapshot".into(), vec![Cell::Literal(snapshot, "string")]),
    ])
}

/// An event on the spine for every write outcome, through the team's logger when this
/// deployment has one (setting `events.command`); without one the line goes to stderr.
pub fn event(command: &str, caller: &str, op: &str, class: &ClassDef, name: &str, result: &str) {
    let fields = [format!("op={op}"), format!("entity={}/{name}", class.plural), format!("result={result}"), format!("api={}-api", crate::model::PRODUCT)];
    if !command.is_empty() && std::path::Path::new(command).exists() {
        let _ = std::process::Command::new("bash").arg(command).arg("owl.write").arg(caller).args(&fields).output();
    } else {
        eprintln!("event owl.write {caller} {}", fields.join(" "));
    }
}

pub fn subject(class: &ClassDef, name: &str) -> String {
    iri(class, name)
}
